style.css:
@-moz-document url-prefix("https://www.roblox.com/home") {
/* overall background & font */
  body, html {
    background: #0f0f0f;
    color: #eee;
    font-family: 'Inter', 'Segoe UI', system-ui, sans-serif;
    transition: background 0.5s ease, color 0.5s ease;
  }

  /* main container responsive */
  #container-main {
    max-width: 1400px;
    margin: 2rem auto;
    padding: 0 2rem;
    display: grid;
    grid-template-columns: 1fr 3fr;
    gap: 2rem;
  }

  /* left side (friends / recommended) */
  .home-container {
    display: flex;
    flex-direction: column;
    gap: 2rem;
    max-width: 350px; /* sidebar fixed width */
  }

  /* right side (games / continue playing) */
  #recommended-games-container,
  #continue-playing-container {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1.5rem;
  }

  /* cards */
  .home-container > div,
  .game-card-container {
    background: rgba(255, 255, 255, 0.07);
    border-radius: 20px;
    padding: 1.5rem;
    box-shadow: 0 8px 20px rgba(0,0,0,0.7);
    transition: transform 0.3s ease, box-shadow 0.3s ease, background 0.3s ease;
    backdrop-filter: blur(8px);
    will-change: transform, box-shadow, background;
  }

  .home-container > div:hover,
  .game-card-container:hover {
    transform: translateY(-8px) scale(1.02);
    box-shadow: 0 14px 32px rgba(0,0,0,0.85);
    background: rgba(255, 255, 255, 0.12);
  }

  /* "Home" title */
  h1, .home-header {
    font-size: 2rem;
    font-weight: 800;
    color: #fff;
    margin-bottom: 1rem;
    text-shadow: 0 0 8px #00ff9c, 0 0 15px #00ff9c;
  }

  /* game thumbnails */
  .game-card-container img {
    border-radius: 16px;
    transition: transform 0.3s ease;
  }

  .game-card-container img:hover {
    transform: scale(1.05) rotate(-1deg);
  }

  /* subtle hover glow for cards */
  .home-container > div:hover,
  .game-card-container:hover {
    box-shadow: 0 0 12px #00ff9c, 0 0 25px rgba(0, 255, 156, 0.5);
  }

  /* responsive tweaks */
  @media (max-width: 768px) {
    #container-main {
      grid-template-columns: 1fr;
      padding: 0 1rem;
    }

    #recommended-games-container,
    #continue-playing-container {
      grid-template-columns: 1fr;
    }

    .home-container {
      max-width: 100%;
    }
  }
}
